"""Evidence-scoped body-composition and eating-safety entries; no prescribing."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
def source(n,citation,url,support,limitations,reading,kind='机构指导',funding='机构公开指导；未列本页专项研究资助。',doi=None):
    s=dict(id=f'NFW-S{n:02d}',citation=citation,url=url,type=kind,support=support,limitations=limitations,reading_depth=reading,funding_disclosure=funding,content_checked_at='2026-10-30')
    if doi:s.update(doi=doi,doi_url='https://doi.org/'+doi)
    return s
sources=[
source(1,'国家卫生健康委员会. 肥胖症诊疗指南（2024年版）[Internet]. 2024 [cited 2026 Oct 30]. Available from: https://www.nhc.gov.cn/cms-search/downFiles/c171fa2416864a21b69278fd04a33f21.pdf','https://www.nhc.gov.cn/cms-search/downFiles/c171fa2416864a21b69278fd04a33f21.pdf','中国成人BMI与腰围分类；BMI在老年人、肌肉发达人群中的局限。','不是每一种药的说明书，也不能用成人BMI诊断儿童；腰围未达到中心性肥胖界值不代表零风险。','直接核读官方79页PDF第4–6页评估与第52页测量、相关药物章节；未把文件年份改成检索年份。','原始临床研究或正式指南'),
source(2,'国家卫生健康委员会办公厅. 体重管理指导原则（2024年版）[Internet]. 2024 [cited 2026 Oct 30]. Available from: https://www.nhc.gov.cn/ylyjs/zcwj/202412/75cb79c171c94def9e768193e65484f7/files/1736390749000_59785.pdf','https://www.nhc.gov.cn/ylyjs/zcwj/202412/75cb79c171c94def9e768193e65484f7/files/1736390749000_59785.pdf','个体化目标、饮食与有氧/抗阻结合、监测和维持；去脂体重包含肌肉以外的组织。','不把指南一般用药原则等同具体产品核准适应证；成人减重目标不直接套给未成年人、孕哺或虚弱老年人。','直接核读官方30页PDF成人/老年评估、饮食运动与行为管理、术语；能量缺口与速度不作为人人固定处方。','原始临床研究或正式指南'),
source(3,'National Institute of Diabetes and Digestive and Kidney Diseases. Choosing a safe and successful weight-loss program [Internet]. [cited 2026 Oct 30]. Available from: https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program','https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program','对有减重需要的成人，以初始体重5%–10%/6个月作为可讨论的起点；可维持的饮食、运动、自我监测。','一般规划例子，不是每个人必须达到的速度；活动收益不能仅按秤上减重判断。','实读项目选择、目标、饮食活动、自我监测及商业警示正文；网页实际更新日未可靠核定，未填日期。'),
source(4,'British Heart Foundation. Why your waist size matters [Internet]. [cited 2026 Oct 30]. Available from: https://www.bhf.org.uk/informationsupport/heart-matters-magazine/medical/measuring-your-waist','https://www.bhf.org.uk/informationsupport/heart-matters-magazine/medical/measuring-your-waist','腰围在肋骨下缘与髋骨上缘间中点水平、自然呼气测量的操作说明。','只用于解释测量操作；没有把英国阈值替换为中国成人诊断标准，腹型特殊者自测会有误差。','实读腹部脂肪、腰围与腰高比测量段；本条不要求读者根据照片操作，未将相关阅读日期当本页更新日期。'),
source(5,'Frija-Masson J, Mullaert J, Vidal-Petiot E, Pons-Kerjean N, Flamant M, d\'Ortho MP. Accuracy of smart scales on weight and body composition: observational study. JMIR Mhealth Uhealth. 2021;9(4):e22487. doi:10.2196/22487.','https://mhealth.jmir.org/2021/4/e22487','所测三款秤的体重较准确，脂肪/肌肉估算与DXA一致性不足；BIA依赖阻抗与推算模型。','法国单中心、2021年三款具体型号；不能外推为所有2026年设备均同样误差，或作品牌排名。','实读原刊完整摘要、方法、结果、讨论局限和利益披露；核三型号样本分别53/52/48，未误写每型号153人。','原始临床研究或正式指南','研究获MSD France对AP-HP基金会的捐赠支持；一位作者披露与本研究无关的企业旅行/住宿支持，其他作者未报冲突。','10.2196/22487'),
source(6,'Binmahfoz A, Dighriri A, Gray C, Gray SR. Effect of resistance exercise on body composition, muscle strength and cardiometabolic health during dietary weight loss in people living with overweight or obesity: a systematic review and meta-analysis. BMJ Open Sport Exerc Med. 2025;11(3):e002363. doi:10.1136/bmjsem-2024-002363.','https://eprints.gla.ac.uk/361857/2/361857.pdf','25项RCT、1608名18–65岁BMI≥25成人：饮食减重加抗阻，对去脂体重保存、脂肪与力量部分结局有益。','去脂体重不全是肌肉；力量证据低确定性，长期依从与≥6个月保存效果有限；不能承诺每个人越练秤上越轻。','从作者大学官方库取得期刊已出版PDF；实读方法、主要结果、讨论局限及资助披露。原刊网页403未绕过，也未声称从原刊读取全文。','系统综述','作者未声明本研究特定资助；未声明利益冲突。','10.1136/bmjsem-2024-002363'),
source(7,'Ramirez-Campillo R, Andrade DC, Clemente FM, Afonso J, Pérez-Castilla A, Gentil P. A proposed model to test the hypothesis of exercise-induced localized fat reduction (spot reduction), including a systematic review with meta-analysis. Hum Mov. 2022;23(3):1–14. doi:10.5114/hm.2022.110373.','https://hummov.awf.wroc.pl/pdf-143162-103926?filename=103926.pdf','13项研究1158人，单侧肢体训练相对另一侧未显示汇总局部减脂优势。','检索截至2021年；单侧肢体模型不能涵盖所有腹部方案或证明未来任何局部效应绝不可能。','直接核读期刊PDF摘要、模型、方法和汇总结果；正式卷期为2022，不因2021在线而拼接年份；本次未完整核实末尾资助段。','系统综述','未完整核实原文资助段，不标作无产业关系。','10.5114/hm.2022.110373'),
source(8,'Food and Drug Administration. Non-invasive body contouring technologies [Internet]. [cited 2026 Oct 30]. Available from: https://www.fda.gov/medical-devices/aesthetic-cosmetic-devices/non-invasive-body-contouring-technologies','https://www.fda.gov/medical-devices/aesthetic-cosmetic-devices/non-invasive-body-contouring-technologies','塑形用途与减重治疗有别；冷冻程序可有冻伤、反常性脂肪增生等，家用冷冻安全有效性未建立。','美国器械监管信息不代表中国注册；不提供具体器械效果排名，也未用罕见并发症推断所有治疗必有害。','实读用途、一般风险、冷冻原理/禁忌/各级并发症及家用警示；页面未可靠核定实际更新日，未填。'),
source(9,'National Institute of Mental Health. Eating disorders: what you need to know [Internet]. 2024 [cited 2026 Oct 30]. Available from: https://www.nimh.nih.gov/health/publications/eating-disorders','https://www.nimh.nih.gov/health/publications/eating-disorders','进食障碍可发生于不同体重、年龄与性别；失控暴食及催吐/泻药/禁食补偿需评估，营养与医疗支持有作用。','不凭单一行为确诊，也不把所有节食当精神疾病；美国药品许可、就诊系统与求助号码未移植中国。','直接实读各类型症状、躯体风险、治疗及就医入口；末尾标Revised 2024，未宣称2026更新。')]

def entry(n,title,summary,plain,benefit,evidence,refs,scope,ages=None):
    return dict(id=f'nutrition-{n:03d}',title=title,summary=summary,fields=dict(cost='',plain=plain,benefit=benefit,evidence=evidence,sources='；'.join('[@NFW-S%02d]'%v for v in refs),notes=''),audience=dict(age_groups=ages or ['adult','older'],sexes=['all'],scope_note=scope,safety_pin=False),clinical_review_status='not_clinically_reviewed',content_checked_at='2026-10-30')
entries=[
entry(20,'想判断该不该减重，先量腰围、算BMI，别凭体脂秤一次读数下结论',
'衣服紧了、体脂秤变红，未必都意味着要继续减重。先用身高体重计算BMI，再按固定方法量腰围，结合血压、血糖和实际体力看健康风险。家用体脂秤的脂肪率、肌肉量属于模型估算，不能当一次体检诊断；儿童、孕期、肌肉发达或虚弱老年人也不能直接套普通成人目标。',
'**先判断有没有减重需要，再决定减多少。** BMI就是体重（千克）除以身高（米）的平方。中国普通成人BMI 18.5至不足24为正常范围，24至不足28为超重，28及以上为肥胖；它是评估入口，不是审美分数。BMI正常也要留意腹部脂肪和代谢问题，肌肉发达的人则可能被BMI高估肥胖程度。[@NFW-S01]\n\n腰围用软尺量：找肋骨下缘与髋骨上缘，两者之间的中点水平绕腹一圈，自然呼气，贴合但不勒进皮肤；固定方法再比较。中国成人男性≥90cm、女性≥85cm达到中心性肥胖界值，低于界值也不是风险自动归零。有腹部明显变化或血压血糖异常时，把记录带去评估。[@NFW-S04][@NFW-S01]\n\n**买普通体重秤和软尺就能开始，不必为“测内脏脂肪年龄”升级。** 家用体脂秤常用生物电阻抗（BIA）：让微弱电流通过身体，再结合身高、年龄等推算成分，并非直接看见脂肪或肌肉。2021年一项三型号研究发现，体重表现优于脂肪/肌肉估算；这不能证明所有新型号都差，但足以提醒：别因今天“掉了1kg肌肉”就临时加餐、停练或买补剂。看相近条件下数周趋势，并结合腰围和力量表现。[@NFW-S05]\n\n未成年人要用年龄、性别对应的生长评估；孕期和虚弱老年人不能追求普通成人低BMI。若秤上数字让你不断少吃、反复补偿，转看[进食失控与过度限制](#/entry/nutrition-023)。减重药门槛另外核，见[药物适用条件](#/entry/nutrition-017)。[@NFW-S01][@NFW-S02]',
'先把是否需要治疗、需要改善什么分清，减少被秤上估算数字牵着走。','C，成人界值与测量属于指南实践；家用秤准确性的B级观察研究只覆盖所测三款型号。',[1,4,5,2],'成人评估与老年限制；儿童、孕期不套本条成人界值。'),
entry(21,'需要减脂就同时安排吃饭和力量训练，用腰围与体力检验计划，不只盯掉秤',
'有减重需要时，先选能长期做到的饮食调整，再把有氧和力量训练排进去。可以把半年减去初始体重的5%作为讨论起点，不必追求每周快速掉秤。体重、腰围和力量一起看：饮食减重加入抗阻训练有助于保留去脂组织，但不保证额外减更多体重；虚弱或已有疾病时，目标需要另定。',
'**先改两三件能重复做的事，而不是同时戒掉主食、晚饭和社交。** 例如把日常含糖饮料换成水、外卖减少一份高油配菜、主食保留但调整分量。对确有减重需要的成人，可与医生或营养人员把6个月减去初始体重的约5%作为第一个讨论目标；有些方案以5%–10%为初始区间，达不到也不是意志力判决。BMI正常且无相关风险的人，不需要照搬减重目标。[@NFW-S03]\n\n**让饮食调整与训练同时存在。** 减重时仍要有正常的主食、蔬菜和蛋白质来源，不靠长期极低进食量换速度；把力量训练加入有氧，按能力逐步增加，具体起步见[运动与活动](#/chapter/activity)。2025年汇总25项试验发现，饮食减重加入抗阻训练，有助于保存去脂体重、减少脂肪并改善部分力量指标，但没有显示明显额外的体重下降。去脂体重包含水、器官、骨骼等，不全等于肌肉；长期效果也受坚持程度影响。[@NFW-S02][@NFW-S06]\n\n固定相近条件，每周记录体重，并间隔记录腰围、日常走路和训练表现，先看数周趋势；短期停滞先检查计划是否还做得到，不立即砍半饭量或加倍训练。若持续无力、头晕、训练倒退，或减重总靠饥饿硬撑，回到营养与医疗评估。瘦不下来又有肥胖相关问题，可讨论[规范药物治疗](#/entry/nutrition-009)。[@NFW-S03][@NFW-S02]',
'让减重更接近减少多余脂肪、保留活动能力，而不是只换取短期更低的秤数。','B，抗阻试验汇总的去脂体重结局为中等确定性、力量为低确定性；C，个体化目标和自我监测来自机构指导。',[3,2,6],'主要供有超重或肥胖相关减重需要的成人；老年尤其虚弱者先评估营养、肌力与疾病，不按年轻人速度减。'),
entry(22,'想改善腰腹和线条，练全身并管理总脂肪，别为“练哪瘦哪”或家用冻脂付费',
'卷腹可以练腹部肌肉，却不能保证把腹部脂肪按指定位置减掉。想改善线条，先分清多余脂肪、肌肉不足和疼痛活动问题，再决定饮食与训练目标。冷冻溶脂等医疗塑形处理局部外观，不替代肥胖治疗；它们有并发症，家用冻脂安全有效性未建立，也别自行拿冰袋模仿。',
'**把“瘦几斤”和“哪里更有线条”分开定目标。** 有多余脂肪时管理整体饮食和活动；想提高力量与肌肉线条时，做循序渐进的全身抗阻训练。BMI正常且没有相关健康问题，不必为了某个部位不断减体重。局部肌肉训练能训练那块肌肉，不代表周围脂肪会按你指定的顺序消失。[@NFW-S02][@NFW-S07]\n\n2022年系统综述汇总13项研究，比较单侧肢体训练和另一侧，未显示汇总的局部减脂优势。它支持对“瘦腿动作保证只瘦腿”保持警惕，但并不证明任何未来方案都绝无局部效应。更实用的选择是把训练当作提升力量与功能的手段，用腰围、力量和持续性看变化，而不是按广告购买“精准燃脂动作套餐”。[@NFW-S07]\n\n**冷冻溶脂、射频塑形属于另一种选择，先核具体器械、操作资质和风险。** 它们处理局部轮廓或外观，并不是治疗肥胖、降低体重或改善代谢健康的替代办法。FDA提醒，冷冻程序可发生冻伤、持续麻木，以及脂肪反而变多变硬的反常性脂肪增生，后者有时需手术处理；家用冷冻设备的安全有效性未建立。不要用冰袋在家模仿。美国监管信息也不能当作中国器械已注册的证明。[@NFW-S08]\n\n如果所谓“体态不好”伴颈背痛、麻木、明显活动受限，先去相应身体部位章节判断和处理，不把减肥或一个通用矫姿动作当作治疗。',
'把饮食、训练和医疗塑形分别放回适合的目标，减少局部速瘦承诺与自行冻伤的风险。','B，局部训练汇总存在模型与年代限制；C，器械用途和风险来自监管指导，不据此排名具体治疗。',[2,7,8],'成人及老年外观选择；虚弱、疼痛或功能异常者先处理身体问题，不默认都要减脂。'),
entry(23,'反复暴食、催吐或越减越不敢吃，先停止惩罚性补偿，尽早评估进食问题',
'如果吃东西经常失控、偷偷大量进食，之后又靠催吐、泻药、长时间禁食或过度运动补偿，问题可能已超出普通饮食选择。进食障碍不只发生在很瘦的人，也不能靠体重正常排除。记录行为与身体不适，寻求医疗和营养支持；不要把继续挨饿、买抑食产品当成补救。',
'**不要等到体重很低，才承认吃饭出了问题。** 反复感到吃不住、因吃饭强烈羞耻，随后靠催吐、泻药、禁食或过度运动“抵消”，都值得评估；这并不等于凭一两次行为就能确诊。进食障碍可发生在不同体重、性别和年龄，体重正常或偏高也不能排除。[@NFW-S09]\n\n先别继续增加惩罚性禁食或运动，也别买更强的抑食产品；把近来的进食、补偿行为、体重变化与正在用的药记下来，尽早向全科、营养或精神心理相关门诊求助。就诊是为了同时处理营养、身体后果与行为问题，不是把它归咎于不自律。若已因反复催吐等出现明显身体不适，不要只在网上换食谱。[@NFW-S09]\n\n治疗可包含医疗监测、营养支持和针对进食行为的心理治疗；这不是要求读者自行完成一套情绪训练。普通减脂计划、体脂秤打卡和减重药不能代替这一评估；有相关病史，开始新一轮减重前也要主动说明。[@NFW-S09]',
'及早识别“继续更狠地减”可能加重的问题，把身体安全与正常进食放在体重数字前。','C，症状线索与就医入口来自机构指导，不能据此自行诊断某一种进食障碍。',[9],'涉及青少年、成人与老年各性别；未成年人宜请可信任成年人陪同评估，不使用成人减重处方。',['teen','adult','older'])]

if __name__=='__main__':
    for kind,value in [('entries',entries),('sources',sources)]:
        (HERE/f'management-{kind}.json').write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    audit=dict(scope='营养、体重体型和进食安全；不扩展完整心理健康百科。',source_access='仅使用实际核读的官方页面、官方原始PDF与期刊/作者机构公开出版物；记录阅读层次及访问限制。',clinical_review_status='not_clinically_reviewed',entry_ids=[e['id'] for e in entries],do_not_infer=['中国成人BMI分类不等于每种药说明书门槛','去脂体重不等于肌肉','未检出局部减脂优势不等于永久绝无任何局部效应','FDA器械信息不等于中国注册','体重正常不排除进食障碍'])
    (HERE/'management-audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print({e['id']:len(e['summary']) for e in entries})
